static int canonical(Cmd c,int side){
if(side!=0)return c;
auto flip=[](int d){return d<2?d^1:d;};
if(is_move(c))return cmd_move(flip(c-1));
if(is_fire(c))return cmd_fire(flip(c-5));
if(is_move2(c))return cmd_move2(flip((c-9)/4),flip((c-9)%4));
return c;
}
